from enum import Enum

class FFmpegCommand:
    inputs: list[FFmpegCommand.Input] = []
    output: str = ""
    hide_banner: bool = False
    metadata: dict[str, str] = {}

    # Returns the ffmpeg command generated by the parameters
    # Returns None if can't generate
    def get_command(self, log_errors: bool = True) -> str | None:
        if len(self.inputs) == 0:
            print("FFMPEG_GENERATOR: get_command() > No inputs were found")
            return None
        if self.output == "":
            print("FFMPEG_GENERATOR: get_command() > No output was specified")
            return None

        command: str = "ffmpeg"
        command += " -loglevel error"
        if self.hide_banner == True:
            command += " -hide_banner"

        for i in self.inputs:
            if i.start != None:
                command += " -ss {}".format(i.start)
            if i.duration != None:
                command += " -t {}".format(i.duration)
            command += ' -i "{}"'.format(i.path)

        for m in self.metadata:
            command += ' -metadata {}="{}"'.format(m, self.metadata[m])

        for i in self.inputs:
            if i.mapped != None:
                command += " -map {}".format(i.mapped)

        command += " -c copy {}".format(self.output)

        return command

    class Input:
        # The path of the input
        path: str = ""
        # Where the input should be mapped
        # If value is None parameter is ignored
        mapped: int | None = None
        # The start time of the input
        # If value is None parameter is ignored
        start: str | None = None
        # The duration of the clip
        # If value is None parameter is ignored
        duration: str | None = None

        def __init__(self, path: str, mapped: int | None = None, start: str | None = None, duration: str | None = None) -> None:
            self.path = path
            self.mapped = mapped
            self.start = start
            self.duration = duration
